#!/usr/bin/env bash
set -euo pipefail
DEST="${ECC_DEST:-$HOME/vhdl_repo/IP_Cores/ECC_Scrubber}"
mkdir -p "$DEST"
echo ">> instalando documentacion en $DEST"
echo "" | base64 -d > "$DEST/README.md"
echo "" | base64 -d > "$DEST/architecture.svg"
echo ">> README secciones: $(grep -c '^## ' "$DEST/README.md")"
echo ">> SVG dimensiones: $(grep -oE 'width=\"760\" height=\"560\"' "$DEST/architecture.svg" | head -1)"
python3 -c "import xml.dom.minidom; xml.dom.minidom.parse('$DEST/architecture.svg'); print('>> SVG XML valido')"
